import json
from itertools import permutations

# Languages each nationality can speak (own language included)
speaks = {
    "South Korea": {"Korean"},
    "France": {"French", "German"},
    "Britain": {"British", "Korean"},
    "Germany": {"Korean", "French", "British", "German"},
}
lang = {"South Korea": "Korean", "France": "French", "Britain": "British", "Germany": "German"}
# Note: "German" language belongs to Germany; France speaks German.

def can_talk(a, b):
    # a can communicate with b if a can speak b's language
    return lang[b] in speaks[a]

options = {
    "A": ["Britain", "Germany", "South Korea", "France"],
    "B": ["France", "Britain", "Germany", "South Korea"],
    "C": ["Germany", "Britain", "France", "South Korea"],
    "D": ["Germany", "Britain", "South Korea", "France"],
}

def neighbors(order, i):
    return [order[j] for j in (i - 1, i + 1) if 0 <= j < len(order)]

def valid(order):
    pos = {n: i for i, n in enumerate(order)}
    # Korean room number larger than German
    if not pos["South Korea"] > pos["Germany"]:
        return False
    # Korean cannot communicate with any neighbor
    k = pos["South Korea"]
    if any(can_talk("South Korea", n) for n in neighbors(order, k)):
        return False
    # French cannot communicate with any neighbor
    f = pos["France"]
    if any(can_talk("France", n) for n in neighbors(order, f)):
        return False
    # British communicates with exactly one neighbor
    b = pos["Britain"]
    if sum(can_talk("Britain", n) for n in neighbors(order, b)) != 1:
        return False
    return True

all_valid = [list(p) for p in permutations(lang.keys()) if valid(p)]
matching = [k for k, v in options.items() if valid(v)]

if len(matching) == 1:
    result = {
        "final_answer": matching[0],
        "evidence": {
            "valid_orders": all_valid,
            "matching_options": matching,
            "order": options[matching[0]],
        },
    }
    print(json.dumps(result))
else:
    print("UNSUPPORTED")
